import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-06-12 :: Ceph Testing Weekly","description":"","frontmatter":{"title":"2019-06-12 :: Ceph Testing Weekly","date":"2019-06-12T00:00:00.000Z","updated":"2019-06-13T00:00:00.000Z","tags":["Ceph","升级降级","smoke测试","测试用例","多操作系统测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-12_-_-_Ceph_Testing_Weekly.md","filePath":"posts/2019/2019-06-12_-_-_Ceph_Testing_Weekly.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-06-12_-_-_Ceph_Testing_Weekly.md"};function o(r,e,n,h,p,_){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>2019年6月12日</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>（未提及具体地点）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>（未提及具体人员）</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. Ceph 升级降级问题</strong></p><ul><li>Josh 和团队成员正在努力实现 Ceph 的降级功能。</li><li>遇到问题，需要提交 PR 进行测试，但相关成员暂时无法完成。</li><li>讨论了基于 Nautilus 的点对点降级模型，并计划将其应用到 Octopus 版本。</li><li>对于跨版本降级，目前还没有具体计划。</li></ul><p><strong>2. smoke 测试</strong></p><ul><li>smoke 测试已通过，主要修复了与 suite 相关的失败任务。</li><li>讨论了是否可以不定期运行 Raiders 测试，以减少测试任务数量并提高效率。</li><li>提出了将测试任务运行在虚拟化环境中的问题，并讨论了使用 OVH 等云服务提供商的可能性。</li></ul><p><strong>3. 测试用例</strong></p><ul><li>讨论了使用快照进行升级和降级的测试用例。</li><li>认为需要在升级前后进行数据一致性和兼容性测试。</li><li>讨论了使用 snapshot 和 binary phase 的可能性和复杂性。</li></ul><p><strong>4. 多操作系统测试</strong></p><ul><li>讨论了多操作系统测试用例的改进。</li><li>认为需要在测试用例中考虑不同操作系统之间的兼容性问题。</li></ul><p><strong>5. 其他事项</strong></p><ul><li>讨论了与 Red Hat 等下游发行版合作的可能性。</li><li>讨论了如何更好地与社区成员沟通和协作。</li></ul><h4 id="行动计划" tabindex="-1">行动计划： <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划：&quot;">​</a></h4><ul><li>Josh 将与相关成员合作，解决降级功能遇到的问题。</li><li>继续优化 smoke 测试，并探讨不定期运行 Raiders 测试的可能性。</li><li>完善测试用例，确保升级和降级操作的安全性。</li><li>改进多操作系统测试用例，提高兼容性。</li><li>加强与社区成员的沟通和协作。</li></ul><h4 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h4><ul><li>Ceph</li><li>升级降级</li><li>smoke测试</li><li>snapshot</li><li>binary phase</li><li>多操作系统测试</li></ul>',22)])])}const c=l(s,[["render",o]]);export{u as __pageData,c as default};
